@section('content')
<div class="grid gap-7 lg:grid-cols-[1fr_320px]"><section><div class="mb-7 flex items-end justify-between gap-4"><div><p class="text-xs font-black uppercase tracking-[.2em] text-indigo-600">Discover</p><h1 class="mt-2 text-4xl font-black tracking-tight sm:text-5xl">People nearby</h1><p class="mt-2 text-slate-500">Real people. Approximate distance. Your location stays private.</p></div><button id="refresh-location" type="button" class="tap hidden rounded-2xl bg-slate-950 px-5 py-3 text-sm font-black text-white shadow-lg sm:block">Find nearby</button></div><div id="location-status" class="mb-5 rounded-3xl border border-indigo-100 bg-gradient-to-r from-indigo-50 to-white p-5 text-sm font-medium text-slate-600" aria-live="polite"><div class="flex gap-3"><span>⌖</span><span>Lami needs your permission to discover people around you. Your exact location is never shown.</span></div></div><div id="people" class="grid gap-4 sm:grid-cols-2"></div></section><aside class="hidden lg:block"><div class="sticky top-24 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><p class="text-xs font-black uppercase tracking-[.18em] text-slate-400">How Lami works</p><div class="mt-5 space-y-5"><div class="flex gap-3"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl bg-slate-100 font-black">1</span><div><p class="font-black">Discover</p><p class="mt-1 text-sm text-slate-500">Find people within your chosen radius.</p></div></div><div class="flex gap-3"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl bg-indigo-50 font-black text-indigo-600">2</span><div><p class="font-black">Wave</p><p class="mt-1 text-sm text-slate-500">Let someone know you'd like to connect.</p></div></div><div class="flex gap-3"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl bg-pink-50 font-black">3</span><div><p class="font-black">Connect</p><p class="mt-1 text-sm text-slate-500">Chat when the feeling is mutual.</p></div></div></div></div></aside></div><div class="fixed bottom-20 left-5 right-5 z-30 sm:hidden"><button id="mobile-find" type="button" class="tap w-full rounded-2xl bg-slate-950 px-5 py-4 font-black text-white shadow-2xl">⌖ Find people nearby</button></div><div id="location-modal" class="fixed inset-0 z-[60] hidden items-end justify-center bg-slate-950/60 p-3 backdrop-blur-sm sm:items-center sm:p-5" role="dialog" aria-modal="true" aria-labelledby="location-title"><div class="w-full max-w-md rounded-[2rem] bg-white p-7 shadow-2xl sm:p-8"><div class="mx-auto flex h-16 w-16 items-center justify-center rounded-3xl bg-slate-950 text-2xl text-white shadow-xl">⌖</div><h2 id="location-title" class="mt-5 text-center text-2xl font-black">Find people around you</h2><p class="mt-3 text-center text-sm leading-6 text-slate-500">Allow location access to discover people nearby. Lami shows distance, not your exact location.</p><button id="allow-location" type="button" class="tap mt-6 w-full rounded-2xl bg-slate-950 px-5 py-4 font-black text-white">Allow location</button><button id="cancel-location" type="button" class="mt-3 w-full rounded-2xl px-5 py-3 font-bold text-slate-500">Not now</button><p id="location-modal-error" class="mt-3 hidden text-center text-sm font-semibold text-red-600" role="alert"></p></div></div>
<script>
const statusBox=document.getElementById('location-status'),peopleBox=document.getElementById('people'),button=document.getElementById('refresh-location'),mobileFind=document.getElementById('mobile-find'),modal=document.getElementById('location-modal'),allow=document.getElementById('allow-location'),cancel=document.getElementById('cancel-location'),modalError=document.getElementById('location-modal-error'),csrf=document.querySelector('meta[name="csrf-token"]')?.content,connectionsBase='{{ url('/connections') }}';let watchId=null,refreshTimer=null,lastAutoSearchAt=0;const AUTO_REFRESH_MS=5*60*1000,WATCH_THROTTLE_MS=30*1000;
function escapeHtml(v=''){const d=document.createElement('div');d.textContent=v;return d.innerHTML}function openModal(){modalError.textContent='';modalError.classList.add('hidden');modal.classList.remove('hidden');modal.classList.add('flex');allow.focus()}function closeModal(){modal.classList.add('hidden');modal.classList.remove('flex')}function setLoading(on){button.disabled=on;mobileFind.disabled=on;button.textContent=on?'Finding…':'Find nearby';mobileFind.textContent=on?'Finding people…':'⌖ Find people nearby'}
async function wave(id,b){b.disabled=true;b.textContent='Sending…';try{const r=await fetch(connectionsBase+'/'+encodeURIComponent(id),{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},credentials:'same-origin'});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||d.errors?.connection?.[0]||'Could not send wave.');b.textContent=d.state==='connected'?'✓ Connected':'✓ Wave sent';b.className='mt-4 w-full rounded-2xl bg-emerald-50 px-4 py-3 text-sm font-black text-emerald-700'}catch(e){b.disabled=false;b.textContent='Try again';b.title=e.message||'Could not send wave';console.error('Lami wave error:',e)}}
function geoMessage(e){if(e.code===1)return'Location permission was denied. Allow location for Lami in your browser/site settings, then try again.';if(e.code===2)return'Your device could not determine your location. Turn on Location Services/GPS and try again.';if(e.code===3)return'Location lookup timed out. Please try again.';return'We could not determine your location. Please try again.'}function position(options){return new Promise((res,rej)=>navigator.geolocation.getCurrentPosition(res,rej,options))}
async function loadNearby(payload,background=false){if(!background)setLoading(true);try{const lr=await fetch('{{ route('location.update') }}',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},credentials:'same-origin',body:JSON.stringify(payload)});const ld=await lr.json().catch(()=>({}));if(!lr.ok)throw new Error(ld.message||'Location could not be saved.');const r=await fetch('{{ route('discover.nearby') }}?latitude='+encodeURIComponent(payload.latitude)+'&longitude='+encodeURIComponent(payload.longitude),{headers:{Accept:'application/json'},credentials:'same-origin'});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'Nearby people could not be loaded.');statusBox.innerHTML='<div class="flex gap-3"><span>✓</span><span>Showing people within '+d.radius_km+' km. Exact locations are hidden. <span class="font-black text-emerald-700">Auto-updating.</span></span></div>';peopleBox.innerHTML=d.people.length?d.people.map(p=>`<article class="group rounded-[1.75rem] border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-start gap-4"><div class="flex h-16 w-16 shrink-0 items-center justify-center overflow-hidden rounded-2xl bg-gradient-to-br from-indigo-100 to-pink-100 text-xl font-black text-indigo-700">${p.avatar?`<img src="${escapeHtml(p.avatar)}" class="h-full w-full object-cover" alt="">`:escapeHtml(p.name.charAt(0).toUpperCase())}</div><div class="min-w-0 flex-1"><div class="flex items-start justify-between gap-2"><h2 class="font-black">${escapeHtml(p.name)}</h2><span class="rounded-full bg-emerald-50 px-2.5 py-1 text-[11px] font-black text-emerald-700">NEARBY</span></div><p class="mt-1 text-sm font-bold text-indigo-600">⌖ ${escapeHtml(p.distance)}</p><p class="mt-3 line-clamp-2 text-sm leading-6 text-slate-500">${escapeHtml(p.bio||'New to Lami')}</p><button type="button" onclick="wave(${p.id},this)" class="mt-4 w-full rounded-2xl bg-slate-950 px-4 py-3 text-sm font-black text-white hover:bg-indigo-600">👋 Wave</button></div></div></article>`).join(''):'<div class="rounded-[1.75rem] border border-dashed border-slate-300 bg-white p-10 text-center sm:col-span-2"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-slate-100 text-xl">⌖</div><h2 class="mt-4 font-black">Nobody nearby yet</h2><p class="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500">Try again later. People need to be discoverable and have recently shared their location.</p></div>';return true}catch(e){if(!background){statusBox.textContent=e.message||'We could not load nearby people. Please try again.';modalError.textContent=e.message||'We could not load nearby people. Please try again.';modalError.classList.remove('hidden')}else console.error('Lami background discover error:',e);return false}finally{if(!background)setLoading(false)}}
async function findPeople(){if(!navigator.geolocation){statusBox.textContent='Your browser does not support location services.';return false}if(!window.isSecureContext){const m='Location access requires HTTPS. Open the HTTPS version of Lami and try again.';statusBox.textContent=m;modalError.textContent=m;modalError.classList.remove('hidden');return false}closeModal();setLoading(true);statusBox.textContent='Requesting your location…';try{let p;try{p=await position({enableHighAccuracy:true,maximumAge:60000,timeout:15000})}catch(e){if(e.code===1)throw e;statusBox.textContent='GPS was slow. Trying again…';p=await position({enableHighAccuracy:false,maximumAge:300000,timeout:20000})}const payload={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy};lastAutoSearchAt=Date.now();const ok=await loadNearby(payload,true);if(ok)startLocationTracking();return ok}catch(e){const m=e.code?geoMessage(e):(e.message||'We could not determine your location. Please try again.');statusBox.textContent=m;if(e.code===1){modalError.textContent=m;modalError.classList.remove('hidden')}return false}finally{setLoading(false)}}
function startLocationTracking(){if(watchId===null&&navigator.geolocation)watchId=navigator.geolocation.watchPosition(async p=>{if(Date.now()-lastAutoSearchAt<WATCH_THROTTLE_MS)return;lastAutoSearchAt=Date.now();await loadNearby({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy},true)},e=>console.warn('Lami location watch:',geoMessage(e)),{enableHighAccuracy:false,maximumAge:60000,timeout:20000});if(!refreshTimer)refreshTimer=setInterval(async()=>{try{const p=await position({enableHighAccuracy:false,maximumAge:60000,timeout:15000});lastAutoSearchAt=Date.now();await loadNearby({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy},true)}catch(e){console.warn('Lami automatic location refresh:',geoMessage(e))}},AUTO_REFRESH_MS)}
async function autoStartIfPermitted(){if(!navigator.geolocation||!window.isSecureContext)return;try{if(navigator.permissions){const permission=await navigator.permissions.query({name:'geolocation'});if(permission.state==='granted')findPeople();permission.onchange=()=>{if(permission.state==='granted')findPeople()}}}catch(e){console.warn('Lami permission check unavailable:',e)}}
button.addEventListener('click',async()=>{if(navigator.permissions){try{if((await navigator.permissions.query({name:'geolocation'})).state==='granted'){await findPeople();return}}catch(e){}}openModal()});mobileFind.addEventListener('click',async()=>{if(navigator.permissions){try{if((await navigator.permissions.query({name:'geolocation'})).state==='granted'){await findPeople();return}}catch(e){}}openModal()});allow.addEventListener('click',findPeople);cancel.addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});autoStartIfPermitted();
</script>
@endsection
